from pathlib import Path

ROOT=Path(__file__).resolve().parent.parent
SRC=ROOT/'buildsrc'
if not (SRC/'backend.py').is_file():
    raise SystemExit(f'buildsrc not found under {ROOT}')

# Version and asset hook
idx=SRC/'app'/'index.html'
h=idx.read_text(encoding='utf-8')
if "const APP_VERSION='4.8.18.2-DESKTOP'" not in h:
    raise SystemExit('Expected v4.8.18.2 UI version not found')
h=h.replace("const APP_VERSION='4.8.18.2-DESKTOP'","const APP_VERSION='4.8.18.3-DESKTOP'",1)
anchor='<link rel="stylesheet" href="v48182_live_excel.css"><script src="v48182_live_excel.js"></script>'
if anchor not in h:
    raise SystemExit('Expected v4.8.18.2 asset anchor not found')
h=h.replace(anchor,anchor+'<link rel="stylesheet" href="v48183_polish.css"><script src="v48183_polish.js"></script>',1)
idx.write_text(h,encoding='utf-8')

# Backend version only; no storage/data-model changes.
be=SRC/'v4179_backend_ext.py'
s=be.read_text(encoding='utf-8')
if "ns['APP_VERSION']='4.8.18.2-DESKTOP'" not in s:
    raise SystemExit('Expected v4.8.18.2 backend version not found')
s=s.replace("ns['APP_VERSION']='4.8.18.2-DESKTOP'","ns['APP_VERSION']='4.8.18.3-DESKTOP'",1)
s=s.replace("Handler.server_version='CompanyInspectionDesktop/4.8.18.2'","Handler.server_version='CompanyInspectionDesktop/4.8.18.3'",1)
be.write_text(s,encoding='utf-8')

# Sub-item attachments: silently persist the parent item/subitems before opening attachment manager.
v=SRC/'app'/'v2026_patch.js'
s=v.read_text(encoding='utf-8')
old="host.onclick=e=>{const att=e.target.closest('[data-subatt]');if(att){if(!subParent){toast('احفظ البند الرئيسي أولاً ثم أضف مرفقات البند الفرعي');return}const rec=subDraft.find(x=>x.id===att.dataset.subatt);openAttachments(subKey(subParent,att.dataset.subatt),'item-subitem','مرفقات البند الفرعي: '+(rec?.name||''));return}const edit=e.target.closest('[data-subedit]');if(edit){openSubEditor(edit.dataset.subedit);return}const del=e.target.closest('[data-subdel]');if(del){const rec=subDraft.find(x=>x.id===del.dataset.subdel);if(!rec||!confirm(`حذف البند الفرعي «${rec.name||''}»؟`))return;subDraft=subDraft.filter(x=>x.id!==del.dataset.subdel);markDirty(byId('itemForm'));renderSubs();closeSubEditor()}};"
new="host.onclick=async e=>{const att=e.target.closest('[data-subatt]');if(att){if(editingSubId)saveSubEditor();const saved=await silentSaveItem();if(!saved){toast('أكمل اسم البند والشركة أولاً لإضافة المرفق');return}subParent=byId('itemId').value||subParent;if(!subParent){toast('تعذر إنشاء البند الرئيسي تلقائيًا');return}const rec=subDraft.find(x=>x.id===att.dataset.subatt);openAttachments(subKey(subParent,att.dataset.subatt),'item-subitem','مرفقات البند الفرعي: '+(rec?.name||''));return}const edit=e.target.closest('[data-subedit]');if(edit){openSubEditor(edit.dataset.subedit);return}const del=e.target.closest('[data-subdel]');if(del){const rec=subDraft.find(x=>x.id===del.dataset.subdel);if(!rec||!confirm(`حذف البند الفرعي «${rec.name||''}»؟`))return;subDraft=subDraft.filter(x=>x.id!==del.dataset.subdel);markDirty(byId('itemForm'));renderSubs();closeSubEditor()}};"
if old not in s:
    raise SystemExit('Expected v4.8.18.2 subitem attachment handler not found')
v.write_text(s.replace(old,new,1),encoding='utf-8')

import zlib,base64
(SRC/'app'/'v48183_polish.js').write_bytes(zlib.decompress(base64.b64decode('')))
(SRC/'app'/'v48183_polish.css').write_bytes(zlib.decompress(base64.b64decode('')))
print('Applied v4.8.18.3 focused UI polish + subitem attachment autosave')
